'use client';

import { correspondeBusca } from '@/lib/busca';
import { useCallback, useEffect, useRef, useState } from 'react';
import {
  AlertTriangle, CheckCircle2, Database, Download, Factory, FileUp, Handshake, History,
  LoaderCircle, LogOut, MessageSquare, PackageSearch, PanelLeftClose, PanelLeftOpen, Pencil, Plus, RefreshCw, Search, Settings, ShieldCheck,
  Trash2, Upload,
} from 'lucide-react';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Checkbox } from '@/components/ui/checkbox';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { NativeSelect, NativeSelectOption } from '@/components/ui/native-select';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Textarea } from '@/components/ui/textarea';

type JsonData = ReturnType<typeof JSON.parse>;
type AnyRow = Record<string, JsonData>;
type Nav = 'search'|'tickets'|'agreements'|'suppliers'|'imports'|'mappings'|'catalogs'|'history'|'admin';

class ApiError extends Error {
  details: AnyRow;
  constructor(data: AnyRow) {
    super(data?.error || 'Não foi possível concluir a operação.');
    this.details = data;
  }
}

async function api<T = JsonData>(path: string, options?: RequestInit): Promise<T> {
  const response = await fetch(path, options);
  const type = response.headers.get('content-type') || '';
  const data: JsonData = type.includes('json') ? await response.json() : await response.text();
  if (response.status === 401 && !path.endsWith('/session') && !path.endsWith('/login')) window.dispatchEvent(new Event('portal:session-expired'));
  if (!response.ok) throw new ApiError(data);
  return data as T;
}

const errorText = (error: unknown) => error instanceof Error ? error.message : 'Não foi possível concluir a operação.';

const money = (value: number) => new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(value ?? 0);
const date = (value?: string|null) => value ? new Intl.DateTimeFormat('pt-BR').format(new Date(`${value.slice(0,10)}T12:00:00`)) : 'Indeterminado';
const cnpj = (value: string) => (value || '').replace(/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})$/, '$1.$2.$3/$4-$5');

export default function PortalApp() {
  const [user,setUser]=useState<AnyRow|null|undefined>(undefined), [data,setData]=useState<AnyRow|null>(null), [nav,setNav]=useState<Nav>('search');
  const [busy,setBusy]=useState(false), [notice,setNotice]=useState<{type:'ok'|'error';text:string}|null>(null), [agreementId,setAgreementId]=useState<string|null>(null);
  const [agreementModal,setAgreementModal]=useState<AnyRow|null>(null), [itemModal,setItemModal]=useState<AnyRow|null>(null), [catalogModal,setCatalogModal]=useState<AnyRow|null>(null);
  const [userList,setUserList]=useState<AnyRow[]>([]), [ticketCount,setTicketCount]=useState<number|undefined>(undefined), [ticketLink,setTicketLink]=useState<string|null>(null);
  const [sidebarCollapsed,setSidebarCollapsed]=useState(false);
  const intentionalLogout=useRef(false);

  const notify=(type:'ok'|'error',text:string)=>{setNotice({type,text});setTimeout(()=>setNotice(null),5000)};
  const refresh=useCallback(async()=>{const next=await api('/api/bootstrap');setUser(next.user);setData(next);void api('/api/users').then(x=>setUserList(x.users||[])).catch(()=>setUserList([]))},[]);
  useEffect(()=>{void api('/api/session').then((x)=>{setUser(x.user);if(x.user)void refresh()}).catch(()=>setUser(null))},[refresh]);
  useEffect(()=>{if(!user)return;let active=true;const linked=new URLSearchParams(window.location.search).get('chamado');if(linked)queueMicrotask(()=>{if(active){setTicketLink(linked);setNav('tickets')}});return()=>{active=false}},[user]);
  useEffect(()=>{const expired=()=>{if(intentionalLogout.current)return;setUser(null);setData(null);setNotice({type:'error',text:'Sua sessão expirou. Entre novamente.'})};window.addEventListener('portal:session-expired',expired);return()=>window.removeEventListener('portal:session-expired',expired)},[]);
  const run=async(fn:()=>Promise<JsonData>,success?:string)=>{setBusy(true);try{const result=await fn();if(success)notify('ok',success);await refresh();return result}catch(error:unknown){notify('error',errorText(error))}finally{setBusy(false)}};

  if(user===undefined) return <Loading label="Preparando sua base de acordos…"/>;
  if(!user) return <Login onLogin={(u)=>{intentionalLogout.current=false;setNotice(null);setUser(u);void refresh()}}/>;
  if(!data) return <Loading label="Carregando acordos…"/>;
  const catalogs=data.catalogs;
  const canWrite=user.role==='admin'||user.role==='editor';
  const isAdmin=user.role==='admin';
  const navigate=(next:Nav)=>{if((next==='history'||next==='admin'||next==='mappings')&&!isAdmin)return;if(['tickets','suppliers','imports','catalogs'].includes(next)&&!canWrite)return;setNav(next);setAgreementId(null)};
  const openAgreement=(id:string)=>{setAgreementId(id);setNav('agreements')};
  const logout=()=>void (async()=>{intentionalLogout.current=true;setBusy(true);try{await api('/api/logout',{method:'POST'});setNotice(null);setUser(null);setData(null)}catch(error:unknown){intentionalLogout.current=false;notify('error',errorText(error))}finally{setBusy(false)}})();
  const removerAcordo=(a:AnyRow,detalhe:AnyRow)=>{
    const condicoes=(detalhe?.items||[]).length, versoes=(detalhe?.versions||[]).length;
    const aviso=[
      `Excluir o acordo ${a.number} de ${a.supplier}?`,
      '',
      `Serão apagadas ${condicoes.toLocaleString('pt-BR')} condição(ões) e ${versoes} versão(ões).`,
      'O histórico de preços deste acordo não poderá ser recuperado.',
      '',
      'Chamados ligados a ele são preservados, apenas perdem o vínculo.',
    ].join('\n');
    if(!confirm(aviso))return;
    void run(async()=>{
      await api(`/api/agreements/${a.id}`,{method:'DELETE'});
      setAgreementId(null);
    },'Acordo excluído.');
  };
  const removeCatalog=(type:string,row:AnyRow)=>{const nome=row.tradeName||row.name||row.code||`${row.city} / ${row.state}`;if(!confirm(`Excluir "${nome}" definitivamente?\n\nSe estiver em uso por algum acordo, a exclusão será recusada.`))return;void run(async()=>{await api(`/api/catalogs/${type}/${row.id}`,{method:'DELETE'})},'Cadastro excluído.')};

  return <main className="min-h-screen bg-background text-foreground">
    <Sidebar nav={nav} setNav={navigate} user={user} counts={{agreements:data.metrics.agreements,imports:data.imports.filter((x:AnyRow)=>x.status==='error').length,tickets:ticketCount}} onLogout={logout} collapsed={sidebarCollapsed} onToggle={()=>setSidebarCollapsed(value=>!value)}/>
    <section className={`pl-16 transition-[padding] duration-300 ${sidebarCollapsed?'lg:pl-16':'lg:pl-56'}`}><div className="mx-auto max-w-[1550px] p-4 sm:p-8">
      {nav==='search'&&<SearchPage catalogs={catalogs} openAgreement={openAgreement}/>}
      {nav==='agreements'&&(agreementId?<AgreementDetail id={agreementId} canWrite={canWrite} isAdmin={isAdmin} onDelete={removerAcordo} onBack={()=>setAgreementId(null)} onEdit={(a:AnyRow)=>setAgreementModal(a)} onItem={(i:AnyRow)=>setItemModal({...i,agreementId})} onImport={()=>navigate('imports')} run={run}/>:<Agreements data={data} canWrite={canWrite} onOpen={setAgreementId} onNew={()=>setAgreementModal({locationIds:[],status:'active',startDate:new Date().toISOString().slice(0,10)})}/>)}
      {canWrite&&nav==='suppliers'&&<CatalogPage type="suppliers" rows={catalogs.suppliers} onAdd={()=>setCatalogModal({type:'suppliers'})} onEdit={(row:AnyRow)=>setCatalogModal({type:'suppliers',...row})} onDelete={(row:AnyRow)=>removeCatalog('suppliers',row)}/>}
      {canWrite&&nav==='imports'&&<Imports data={data} run={run} busy={busy}/>}
      {isAdmin&&nav==='mappings'&&<Mappings catalogs={catalogs} run={run}/>}
      {canWrite&&nav==='catalogs'&&<Catalogs data={data} onAdd={(type:string)=>setCatalogModal({type})} onEdit={(type:string,row:AnyRow)=>setCatalogModal({type,...row})} onDelete={removeCatalog}/>}
      {canWrite&&nav==='tickets'&&<Tickets users={userList} run={run} refreshCounts={setTicketCount} initialDetail={ticketLink}/>}
      {isAdmin&&nav==='history'&&<ChangeHistory users={userList}/>}
      {isAdmin&&nav==='admin'&&<Administration user={user} initialUsers={userList} run={run}/>}
      {isAdmin&&nav==='admin'&&<EmailQueue run={run}/>}
    </div></section>
    {notice&&<div className={`fixed bottom-5 right-5 z-[100] flex max-w-md items-center gap-3 rounded-xl px-4 py-3 text-sm font-medium text-white shadow-2xl ${notice.type==='ok'?'bg-emerald-700':'bg-red-700'}`}>{notice.type==='ok'?<CheckCircle2 className="size-5"/>:<AlertTriangle className="size-5"/>}{notice.text}</div>}
    {agreementModal&&<AgreementDialog open value={agreementModal} catalogs={catalogs} busy={busy} onClose={()=>setAgreementModal(null)} onSave={(body:AnyRow)=>run(async()=>{if(body.id)await api(`/api/agreements/${body.id}`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(body)});else await api('/api/agreements',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});setAgreementModal(null)},body.id?'Acordo atualizado.':'Acordo criado.')}/>}
    {itemModal&&<ItemDialog open value={itemModal} catalogs={catalogs} busy={busy} onClose={()=>setItemModal(null)} onSave={(body:AnyRow)=>run(async()=>{if(body.id)await api(`/api/items/${body.id}`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(body)});else await api(`/api/agreements/${body.agreementId}/items`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});setItemModal(null)},'Condição salva.')}/>}
    {catalogModal&&<CatalogDialog open value={catalogModal} busy={busy} onClose={()=>setCatalogModal(null)} onSave={(body:AnyRow)=>run(async()=>{const path=body.id?`/api/catalogs/${body.type}/${body.id}`:`/api/catalogs/${body.type}`;await api(path,{method:body.id?'PUT':'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});setCatalogModal(null)},'Cadastro salvo.')}/>}
  </main>;
}

function Loading({label}:{label:string}){return <div className="grid min-h-screen place-items-center bg-[#eef2f5]"><div className="flex items-center gap-3 rounded-2xl bg-white px-6 py-5 shadow-lg"><LoaderCircle className="size-5 animate-spin text-primary"/><span className="text-sm font-medium">{label}</span></div></div>}
function Login({onLogin}:{onLogin:(u:AnyRow)=>void}){const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);const submit=async(e:React.SyntheticEvent<HTMLFormElement>)=>{e.preventDefault();setBusy(true);setError('');try{const x=await api('/api/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email,password})});onLogin(x.user)}catch(err:unknown){setError(errorText(err))}finally{setBusy(false)}};return <main className="relative grid min-h-screen place-items-center overflow-hidden bg-[#0a1420] p-6"><div className="pointer-events-none absolute inset-0 opacity-70 [background-image:radial-gradient(ellipse_at_15%_10%,rgba(45,212,191,.20)_0,transparent_45%),radial-gradient(ellipse_at_85%_80%,rgba(56,189,248,.16)_0,transparent_45%)]"/><div className="pointer-events-none absolute inset-0 opacity-[.05] [background-image:linear-gradient(rgba(255,255,255,.6)_1px,transparent_1px),linear-gradient(90deg,rgba(255,255,255,.6)_1px,transparent_1px)] [background-size:56px_56px]"/><section className="relative w-full max-w-md space-y-6 animate-in fade-in zoom-in-95 duration-500"><h1 className="text-center text-4xl font-semibold tracking-[-.04em] text-white sm:text-5xl">Portal Suprimentos</h1><Card className="border-white/10 bg-white p-3 text-foreground shadow-[0_30px_80px_-20px_rgb(0_0_0/.55)]"><CardContent className="pt-6"><form className="space-y-4" onSubmit={submit}><Field label="E-mail"><Input className="h-11" type="email" autoComplete="username" value={email} onChange={e=>setEmail(e.target.value)}/></Field><Field label="Senha"><Input className="h-11" type="password" autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)}/></Field>{error&&<Alert variant="destructive" className="animate-in fade-in slide-in-from-top-1"><AlertTriangle/><AlertTitle>Não foi possível entrar</AlertTitle><AlertDescription>{error}</AlertDescription></Alert>}<Button type="submit" className="h-11 w-full transition-transform active:scale-[.985]" disabled={busy||!email||!password}>{busy?<LoaderCircle className="animate-spin"/>:<ShieldCheck/>} Entrar</Button></form></CardContent></Card></section></main>}

const navItems=[{id:'search',label:'Buscar',icon:PackageSearch},{id:'tickets',label:'Chamados',icon:MessageSquare},{id:'agreements',label:'Acordos',icon:Handshake},{id:'suppliers',label:'Fornecedores',icon:Factory},{id:'imports',label:'Importações',icon:FileUp}] as const;
function Sidebar({nav,setNav,user,counts,onLogout,collapsed,onToggle}:JsonData){const canWrite=user.role==='admin'||user.role==='editor',isAdmin=user.role==='admin';const visible=navItems.filter((x:JsonData)=>canWrite||x.id==='search'||x.id==='agreements');const nameParts=user.name.trim().split(/\s+/),firstName=nameParts[0]||user.name,initials=nameParts.length>1?nameParts[0][0]+(nameParts.at(-1)?.[0]||''):firstName.slice(0,2);return <aside className={`fixed inset-y-0 left-0 z-30 flex w-16 flex-col overflow-hidden border-r border-sidebar-border bg-sidebar text-sidebar-foreground transition-[width] duration-300 ${collapsed?'lg:w-16':'lg:w-56'}`}><div className="pointer-events-none absolute inset-0 opacity-60 [background-image:radial-gradient(ellipse_at_20%_0%,rgba(45,212,191,.14)_0,transparent_55%)]"/><nav className="relative flex-1 space-y-1 overflow-y-auto px-2 py-5 text-sm lg:px-3"><button type="button" onClick={onToggle} title={collapsed?'Expandir barra lateral':'Recolher barra lateral'} aria-label={collapsed?'Expandir barra lateral':'Recolher barra lateral'} aria-expanded={!collapsed} className="mb-3 hidden w-full items-center gap-3 rounded-lg px-3 py-2 text-left text-xs opacity-45 transition-colors hover:bg-sidebar-accent hover:opacity-100 lg:flex">{collapsed?<PanelLeftOpen className="size-4 shrink-0"/>:<PanelLeftClose className="size-4 shrink-0"/>}{!collapsed&&<span className="truncate">Recolher menu</span>}</button><div className="mb-3 hidden h-px bg-sidebar-border lg:block"/>{visible.map((x:JsonData)=><NavButton key={x.id} {...x} active={nav===x.id} onClick={()=>setNav(x.id)} count={x.id==='agreements'?counts.agreements:x.id==='imports'&&counts.imports?counts.imports:x.id==='tickets'&&counts.tickets?counts.tickets:undefined} collapsed={collapsed}/>)}{canWrite&&<>{!collapsed&&<p className="hidden px-3 pb-2 pt-6 text-[10px] font-bold uppercase tracking-[.15em] opacity-30 lg:block">Gestão</p>}<div className={`my-3 h-px bg-sidebar-border ${collapsed?'':'lg:hidden'}`}/><NavButton label="Cadastros" icon={Database} active={nav==='catalogs'} onClick={()=>setNav('catalogs')} collapsed={collapsed}/>{isAdmin&&<><NavButton label="De/Para" icon={RefreshCw} active={nav==='mappings'} onClick={()=>setNav('mappings')} collapsed={collapsed}/><NavButton label="Histórico" icon={History} active={nav==='history'} onClick={()=>setNav('history')} collapsed={collapsed}/><NavButton label="Usuários" icon={Settings} active={nav==='admin'} onClick={()=>setNav('admin')} collapsed={collapsed}/></>}</>}</nav><div className={`relative border-t border-sidebar-border p-2 ${collapsed?'lg:p-2':'lg:p-3'}`}><div className={`flex items-center gap-3 rounded-xl bg-sidebar-accent p-2 ${collapsed?'lg:flex-col':'lg:p-3'}`}><div className="grid size-8 shrink-0 place-items-center rounded-full bg-gradient-to-br from-teal-300 to-cyan-400 text-xs font-bold text-[#06202b]">{initials}</div>{!collapsed&&<div className="hidden min-w-0 flex-1 lg:block"><p className="truncate text-sm font-semibold">{firstName}</p></div>}<Button className="hidden lg:inline-flex" size="icon-sm" variant="ghost" onClick={onLogout} aria-label="Sair" title="Sair"><LogOut/></Button></div><Button className="mt-2 w-full lg:hidden" size="icon-sm" variant="ghost" onClick={onLogout} aria-label="Sair"><LogOut/></Button></div></aside>}
function NavButton({label,icon:Icon,active,onClick,count,collapsed}:JsonData){return <button onClick={onClick} title={label} className={`group relative flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left transition-all duration-200 ${active?'bg-sidebar-primary text-sidebar-primary-foreground shadow-sm':'opacity-55 hover:translate-x-0.5 hover:bg-sidebar-accent hover:opacity-100'}`}>{active&&<span className="absolute left-0 top-1/2 h-5 w-[3px] -translate-y-1/2 rounded-r-full bg-teal-300"/>}<Icon className="size-4 shrink-0"/>{!collapsed&&<span className="hidden flex-1 truncate lg:block">{label}</span>}{count!==undefined&&!collapsed&&<span className="hidden rounded-full bg-white/10 px-2 text-xs tabular-nums lg:inline">{count}</span>}</button>}



function SearchPage({catalogs,openAgreement}:JsonData){const [filters,setFilters]=useState({state:'',item:'',model:'',supplier:'',location:''}),[rows,setRows]=useState<AnyRow[]>([]),[meta,setMeta]=useState<AnyRow>({}),[loading,setLoading]=useState(false),[searched,setSearched]=useState(false);const states=Array.from(new Set((catalogs.locations||[]).map((x:AnyRow)=>x.state).filter(Boolean))).sort((a,b)=>String(a).localeCompare(String(b),'pt-BR')).map((uf)=>({id:uf,name:uf}));const locationRows=filters.state?(catalogs.locations||[]).filter((x:AnyRow)=>x.state===filters.state):catalogs.locations;const search=async()=>{setLoading(true);try{const p=new URLSearchParams(Object.entries(filters).filter(([,v])=>v));const x=await api(`/api/search?${p}`);setRows(x.rows);setMeta({total:x.total,truncated:x.truncated,limit:x.limit});setSearched(true)}finally{setLoading(false)}};return <div className="space-y-5"><Card className="overflow-hidden"><CardContent className="grid gap-3 pt-5 md:grid-cols-2 xl:grid-cols-5"><SelectField label="Estado" value={filters.state} onChange={(v:string)=>setFilters({...filters,state:v,location:''})} rows={states}/><SelectField label="Cidade" value={filters.location} onChange={(v:string)=>setFilters({...filters,location:v})} rows={locationRows} labelFn={(x:AnyRow)=>`${x.city} / ${x.state}`}/><SelectField label="Peça ou serviço" value={filters.item} onChange={(v:string)=>setFilters({...filters,item:v})} rows={catalogs.items}/><SelectField label="Modelo" value={filters.model} onChange={(v:string)=>setFilters({...filters,model:v})} rows={catalogs.models}/><SelectField label="Fornecedor" value={filters.supplier} onChange={(v:string)=>setFilters({...filters,supplier:v})} rows={catalogs.suppliers} labelFn={(x:AnyRow)=>x.tradeName}/><div className="flex items-center justify-between gap-3 md:col-span-2 xl:col-span-5"><Button variant="ghost" className="text-muted-foreground" onClick={()=>{setFilters({state:'',item:'',model:'',supplier:'',location:''});setSearched(false);setRows([])}}>Limpar filtros</Button><Button size="lg" className="transition-transform active:scale-[.97]" onClick={search} disabled={loading}>{loading?<LoaderCircle className="animate-spin"/>:<Search/>} Pesquisar</Button></div></CardContent></Card>{searched?<Card><CardHeader className="border-b"><CardTitle>{meta.truncated?`Mostrando ${rows.length.toLocaleString('pt-BR')} de ${Number(meta.total).toLocaleString('pt-BR')} condições`:`${Number(meta.total??rows.length).toLocaleString('pt-BR')} condições encontradas`}</CardTitle>{meta.truncated&&<Alert variant="destructive" className="mt-3"><AlertTriangle/><AlertTitle>Resultado incompleto</AlertTitle><AlertDescription>A consulta encontrou {Number(meta.total).toLocaleString('pt-BR')} condições e apenas as {rows.length.toLocaleString('pt-BR')} primeiras estão na tabela. Use os filtros de item, modelo, cidade ou fornecedor para reduzir a lista antes de comparar preços.</AlertDescription></Alert>}</CardHeader><CardContent className="px-0 pb-0"><Table><TableHeader><TableRow><TableHead>Peça / serviço</TableHead><TableHead>Modelo</TableHead><TableHead>Fornecedor</TableHead><TableHead>Cidade</TableHead><TableHead>Marcas</TableHead><TableHead>Unidade</TableHead><TableHead className="text-right">Preço</TableHead></TableRow></TableHeader><TableBody>{rows.map(r=><TableRow key={r.id}><TableCell className="font-medium"><button className="text-left text-primary hover:underline" onClick={()=>openAgreement(r.agreementId)}>{r.item}</button></TableCell><TableCell>{r.model}</TableCell><TableCell><p className="font-medium">{r.supplier}</p><p className="text-xs text-muted-foreground">{r.number}</p>{r.provisional?<Badge className="mt-1 bg-amber-50 text-amber-700">Vigência não confirmada</Badge>:null}</TableCell><TableCell>{r.city} / {r.state}</TableCell><TableCell className="max-w-64 truncate text-muted-foreground">{r.brands||'Livre'}</TableCell><TableCell>{r.unit}</TableCell><TableCell className="text-right font-semibold tabular-nums">{r.courtesy?<Badge className="bg-sky-50 text-sky-700">Cortesia</Badge>:money(r.price)}</TableCell></TableRow>)}</TableBody></Table></CardContent></Card>:<Empty icon={Search} title="Monte sua pesquisa" text="Use um ou mais filtros para consultar as condições vigentes."/>}</div>}

function Agreements({data,onOpen,onNew,canWrite}:JsonData){const [q,setQ]=useState(''),[status,setStatus]=useState('');const rows=data.agreements.filter((r:AnyRow)=>(!q||correspondeBusca(`${r.number} ${r.supplier} ${r.cnpj} ${r.locations}`,q))&&(!status||r.effectiveStatus===status));return <div className="space-y-5"><div className="flex flex-wrap gap-3"><div className="relative min-w-64 flex-1"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground"/><Input className="pl-9" placeholder="Número, fornecedor, CNPJ ou cidade" value={q} onChange={e=>setQ(e.target.value)}/></div><NativeSelect className="w-48" value={status} onChange={e=>setStatus(e.target.value)}><NativeSelectOption value="">Todas as situações</NativeSelectOption><NativeSelectOption value="active">Vigente</NativeSelectOption><NativeSelectOption value="expired">Expirado</NativeSelectOption><NativeSelectOption value="suspended">Suspenso</NativeSelectOption></NativeSelect>{canWrite&&<Button onClick={onNew}><Plus/> Novo</Button>}</div><AgreementTable rows={rows} onOpen={onOpen} title={`${rows.length} acordos`}/></div>}
function AgreementTable({rows,onOpen,title}:JsonData){return <Card><CardHeader className="border-b"><CardTitle>{title}</CardTitle></CardHeader><CardContent className="px-0 pb-0"><Table><TableHeader><TableRow><TableHead>Acordo</TableHead><TableHead>Fornecedor</TableHead><TableHead>Localidades</TableHead><TableHead>Itens</TableHead><TableHead>Situação</TableHead><TableHead>Vigência</TableHead></TableRow></TableHeader><TableBody>{rows.map((r:AnyRow)=><TableRow key={r.id}><TableCell><button className="text-left" onClick={()=>onOpen(r.id)}><span className="block font-mono text-xs font-semibold text-primary hover:underline">{r.number}</span>{r.provisional?<Badge className="mt-1 bg-slate-100 text-slate-600">Provisório</Badge>:null}</button></TableCell><TableCell><p className="font-medium">{r.supplier}</p><p className="text-xs text-muted-foreground">{cnpj(r.cnpj)}</p></TableCell><TableCell className="max-w-72 truncate">{r.locations||'—'}</TableCell><TableCell>{Number(r.itemCount).toLocaleString('pt-BR')}</TableCell><TableCell><Status value={r.effectiveStatus||r.status}/></TableCell><TableCell>{date(r.endDate)}</TableCell></TableRow>)}</TableBody></Table></CardContent></Card>}

function AgreementDetail({id,canWrite,isAdmin,onBack,onEdit,onItem,onImport,onDelete,run}:JsonData){const [detail,setDetail]=useState<AnyRow|null>(null),[q,setQ]=useState('');const load=useCallback(()=>api(`/api/agreements/${id}`).then(setDetail),[id]);useEffect(()=>{void load()},[load]);if(!detail)return <Loading label="Abrindo acordo…"/>;const a=detail.agreement, items=detail.items.filter((x:AnyRow)=>!q||correspondeBusca(`${x.item} ${x.model} ${x.city} ${x.brands}`,q));return <div className="space-y-5"><div className="flex flex-wrap items-center gap-3"><Button variant="outline" onClick={onBack}>← Voltar</Button><div className="min-w-0 flex-1"><div className="flex items-center gap-2"><h2 className="truncate text-2xl font-semibold">{a.number}</h2>{a.provisional?<Badge className="bg-slate-100 text-slate-600">Completar cadastro</Badge>:<Status value={a.effectiveStatus||a.status}/>}</div><p className="text-sm text-muted-foreground">{a.supplier} · {cnpj(a.cnpj)}</p></div>{canWrite&&<><Button variant="outline" onClick={()=>onEdit({...a,locationIds:detail.locations.map((x:AnyRow)=>x.id),supplierId:a.supplier_id,startDate:a.start_date,endDate:a.end_date})}><Pencil/> Editar acordo</Button><Button variant="outline" onClick={onImport}><Upload/> Substituir tabela</Button>{isAdmin&&<Button variant="outline" className="text-destructive hover:bg-destructive/10" onClick={()=>onDelete(a,detail)}><Trash2/> Excluir acordo</Button>}<Button onClick={()=>onItem({agreementId:id,modelIds:[],price:''})}><Plus/> Nova condição</Button></>}</div><section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Info label="Situação" value={a.provisional?'Provisório':statusName(a.effectiveStatus||a.status)}/><Info label="Início" value={date(a.start_date)}/><Info label="Fim" value={date(a.end_date)}/><Info label="Versões" value={String(detail.versions.length)}/></section><Card><CardHeader className="border-b sm:grid-cols-[1fr_auto]"><div><CardTitle>Tabela vigente</CardTitle><p className="mt-1 text-sm text-muted-foreground">{detail.items.length.toLocaleString('pt-BR')} condições publicadas em {detail.locations.length} localidade(s).</p></div><div className="relative"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground"/><Input className="pl-9" placeholder="Filtrar tabela" value={q} onChange={e=>setQ(e.target.value)}/></div></CardHeader><CardContent className="max-h-[62vh] overflow-auto px-0 pb-0"><Table><TableHeader className="sticky top-0 z-10 bg-card"><TableRow><TableHead>Item</TableHead><TableHead>Modelo</TableHead><TableHead>Local</TableHead><TableHead>Marcas</TableHead><TableHead>Unid.</TableHead><TableHead className="text-right">Preço</TableHead>{canWrite&&<TableHead><span className="sr-only">Ações</span></TableHead>}</TableRow></TableHeader><TableBody>{items.map((r:AnyRow)=><TableRow key={r.id}><TableCell className="font-medium">{r.item}</TableCell><TableCell>{r.model}</TableCell><TableCell>{r.city} / {r.state}</TableCell><TableCell className="max-w-56 truncate text-muted-foreground">{r.brands||'Livre'}</TableCell><TableCell>{r.unit}</TableCell><TableCell className="text-right font-semibold">{r.courtesy?<Badge className="bg-sky-50 text-sky-700">Cortesia</Badge>:money(r.price)}</TableCell>{canWrite&&<TableCell><div className="flex justify-end gap-1"><Button size="icon-sm" variant="ghost" aria-label="Editar condição" onClick={()=>onItem({...r,agreementId:id,modelIds:[r.modelId]})}><Pencil/></Button><Button size="icon-sm" variant="ghost" aria-label="Remover condição" className="text-destructive" onClick={()=>confirm('Remover esta condição?')&&run(async()=>{await api(`/api/items/${r.id}`,{method:'DELETE'});await load()},'Condição removida.')}><Trash2/></Button></div></TableCell>}</TableRow>)}</TableBody></Table></CardContent></Card></div>}
function Info({label,value}:JsonData){return <Card size="sm"><CardContent><p className="text-xs text-muted-foreground">{label}</p><p className="mt-1 font-semibold">{value}</p></CardContent></Card>}

function CatalogPage({type,rows,onAdd,onEdit,onDelete}:JsonData){const [q,setQ]=useState('');const names:AnyRow={suppliers:['Fornecedores'],items:['Peças e serviços'],models:['Modelos de veículos'],units:['Unidades de medida'],brands:['Marcas aceitas'],locations:['Localidades']};const list=rows.filter((r:AnyRow)=>correspondeBusca(JSON.stringify(r),q));return <div className="space-y-5"><div className="flex gap-3"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground"/><Input className="pl-9" placeholder={`Pesquisar ${names[type][0].toLowerCase()}`} value={q} onChange={e=>setQ(e.target.value)}/></div><Button onClick={onAdd}><Plus/> Novo</Button></div><Card><CardHeader className="border-b"><CardTitle>{names[type][0]} · {list.length}</CardTitle></CardHeader><CardContent className="px-0 pb-0"><Table><TableHeader><TableRow>{catalogHeaders(type).map(x=><TableHead key={x}>{x}</TableHead>)}<TableHead/></TableRow></TableHeader><TableBody>{list.map((r:AnyRow)=><TableRow key={r.id}>{catalogCells(type,r).map((x,i)=><TableCell key={i} className={i===0?'font-medium':''}>{x}</TableCell>)}<TableCell><div className="flex justify-end gap-1"><Button size="icon-sm" variant="ghost" aria-label="Editar" onClick={()=>onEdit(r)}><Pencil/></Button>{onDelete&&<Button size="icon-sm" variant="ghost" aria-label="Excluir" className="text-destructive hover:bg-destructive/10" onClick={()=>onDelete(r)}><Trash2/></Button>}</div></TableCell></TableRow>)}</TableBody></Table></CardContent></Card></div>}
function Catalogs({data,onAdd,onEdit,onDelete}:JsonData){const [type,setType]=useState('items');const labels:AnyRow={items:'Peças e serviços',models:'Modelos',units:'Unidades',brands:'Marcas',locations:'Localidades'};return <div className="space-y-5"><div className="flex flex-wrap gap-2">{Object.entries(labels).map(([k,v])=><Button key={k} variant={type===k?'default':'outline'} onClick={()=>setType(k)}>{String(v)}</Button>)}</div><CatalogPage type={type} rows={data.catalogs[type]} onAdd={()=>onAdd(type)} onEdit={(row:AnyRow)=>onEdit(type,row)} onDelete={(row:AnyRow)=>onDelete(type,row)}/></div>}
function catalogHeaders(type:string){if(type==='suppliers')return['Nome','Razão social','CNPJ','Cidade','UF','Situação'];if(type==='locations')return['Cidade','UF'];if(type==='units')return['Código','Descrição','Situação'];if(type==='items')return['Nome','Situação'];return['Nome','Situação']}
function catalogCells(type:string,r:AnyRow){if(type==='suppliers')return[r.tradeName,r.legalName,cnpj(r.cnpj),r.city||'—',r.state||'—',r.active?'Ativo':'Inativo'];if(type==='locations')return[r.city,r.state];if(type==='units')return[r.code,r.name,r.active?'Ativa':'Inativa'];if(type==='items')return[r.name,r.active?'Ativo':'Inativo'];return[r.name,r.active?'Ativo':'Inativo']}

function Imports({data,run,busy}:JsonData){
  const [failure,setFailure]=useState<AnyRow|null>(null),[history,setHistory]=useState<AnyRow[]|null>(null);
  const [mode,setMode]=useState<'legacy'|'agreement'>('legacy'),[agreement,setAgreement]=useState(''),[file,setFile]=useState<File|null>(null),[fileError,setFileError]=useState(''),[drag,setDrag]=useState(false);
  const fileInput=useRef<HTMLInputElement>(null);
  const choose=(candidate?:File|null)=>{setFileError('');setFailure(null);if(!candidate){setFile(null);return}if(!/\.(xlsx|xls)$/i.test(candidate.name)){setFile(null);setFileError('Selecione um arquivo Excel .xlsx ou .xls.');return}if(candidate.size>15*1024*1024){setFile(null);setFileError('A planilha ultrapassa o limite de 15 MB.');return}setFile(candidate)};
  const send=async()=>{if(!file||busy)return;setFailure(null);const form=new FormData();form.set('file',file);const path=mode==='legacy'?'/api/imports/legacy':`/api/imports/agreement/${agreement}`;const result=await run(async()=>{try{return await api(path,{method:'POST',body:form})}catch(error){setFailure(error instanceof ApiError?error.details:{error:errorText(error)});throw error}finally{try{const latest=await api('/api/imports');setHistory(latest.imports)}catch{/* mantém o histórico visível se a conexão cair */}}},'Importação concluída e publicada.');if(result)setFile(null)};
  return <div className="mx-auto max-w-3xl"><div className="space-y-5"><Card><CardHeader><CardTitle>Nova importação</CardTitle></CardHeader><CardContent className="space-y-5"><div className="grid gap-3 sm:grid-cols-2"><button onClick={()=>setMode('legacy')} className={`rounded-xl border p-4 text-left ${mode==='legacy'?'border-primary bg-accent/40 ring-2 ring-primary/10':'hover:bg-muted/40'}`}><Database className="mb-3 size-5 text-primary"/><p className="font-semibold">Carga inicial completa</p><p className="mt-1 text-xs text-muted-foreground">Cria acordos provisórios agrupados por CNPJ.</p></button><button onClick={()=>setMode('agreement')} className={`rounded-xl border p-4 text-left ${mode==='agreement'?'border-primary bg-accent/40 ring-2 ring-primary/10':'hover:bg-muted/40'}`}><RefreshCw className="mb-3 size-5 text-primary"/><p className="font-semibold">Substituir um acordo</p><p className="mt-1 text-xs text-muted-foreground">Publica uma nova versão completa da tabela.</p></button></div>{mode==='agreement'&&<SelectField label="Acordo de destino" value={agreement} onChange={setAgreement} rows={data.agreements} labelFn={(x:AnyRow)=>`${x.number} · ${x.supplier}`}/>}<input ref={fileInput} className="hidden" type="file" accept=".xlsx,.xls" onChange={e=>choose(e.target.files?.[0])}/><button type="button" onClick={()=>fileInput.current?.click()} onDragOver={e=>{e.preventDefault();setDrag(true)}} onDragLeave={()=>setDrag(false)} onDrop={e=>{e.preventDefault();setDrag(false);choose(e.dataTransfer.files[0])}} className={`grid w-full cursor-pointer place-items-center rounded-2xl border-2 border-dashed p-8 text-center transition sm:p-10 ${drag?'border-primary bg-accent/30':'border-border bg-muted/20 hover:border-primary/45'}`}><div className="grid size-12 place-items-center rounded-xl bg-background text-primary shadow-sm"><Upload/></div><p className="mt-4 max-w-full truncate font-semibold">{file?file.name:'Arraste a planilha ou clique para selecionar'}</p><p className="mt-1 text-xs text-muted-foreground">Excel .xlsx ou .xls · até 15 MB · máximo de 50 mil linhas.</p></button>{fileError&&<Alert variant="destructive"><AlertTriangle/><AlertTitle>Arquivo inválido</AlertTitle><AlertDescription>{fileError}</AlertDescription></Alert>}{failure&&<ImportFailure failure={failure}/>}<div className="flex justify-end"><Button size="lg" onClick={()=>void send()} disabled={busy||!file||(mode==='agreement'&&!agreement)}><Upload/> Validar e publicar</Button></div></CardContent></Card><ImportHistory rows={history||data.imports}/></div></div>}
function ImportHistory({rows}:JsonData){const [detail,setDetail]=useState<AnyRow|null>(null),[loading,setLoading]=useState(false);const open=async(id:string)=>{setLoading(true);try{setDetail(await api(`/api/imports/${id}`))}finally{setLoading(false)}};return <><Card><CardHeader className="border-b"><CardTitle>Histórico de importações</CardTitle></CardHeader><CardContent className="px-0 pb-0"><Table><TableHeader><TableRow><TableHead>Arquivo</TableHead><TableHead>Tipo</TableHead><TableHead>Linhas</TableHead><TableHead>Situação</TableHead><TableHead>Data</TableHead></TableRow></TableHeader><TableBody>{rows.map((r:AnyRow)=><TableRow key={r.id}><TableCell><button className="text-left hover:underline" onClick={()=>void open(r.id)}><span className="block font-medium">{r.filename}</span><span className="block text-xs text-muted-foreground">{r.agreement||'Base inicial'}</span></button></TableCell><TableCell>{r.mode==='legacy'?'Carga inicial':'Substituição'}</TableCell><TableCell>{Number(r.totalRows).toLocaleString('pt-BR')}</TableCell><TableCell><Badge className={r.status==='completed'?'bg-emerald-50 text-emerald-700':r.status==='error'?'bg-red-50 text-red-700':'bg-amber-50 text-amber-700'}>{r.status==='completed'?'Concluída':r.status==='error'?'Com erro':'Processando'}</Badge></TableCell><TableCell>{date(r.createdAt)}</TableCell></TableRow>)}</TableBody></Table>{!rows.length&&<div className="p-8 text-center text-sm text-muted-foreground">Nenhuma importação registrada.</div>}</CardContent></Card><Dialog open={!!detail||loading} onOpenChange={value=>!value&&setDetail(null)}><DialogContent><DialogHeader><DialogTitle>{loading?'Carregando detalhes…':detail?.filename}</DialogTitle><DialogDescription>{detail?`${detail.agreement||'Base inicial'} · ${new Date(detail.createdAt).toLocaleString('pt-BR')}`:'Aguarde um instante.'}</DialogDescription></DialogHeader>{detail&&<div className="space-y-4 text-sm"><div className="grid grid-cols-3 gap-2"><Info label="Linhas" value={String(detail.totalRows||0)}/><Info label="Válidas" value={String(detail.validRows||0)}/><Info label="Com erro" value={String(detail.errorRows||0)}/></div>{detail.summary?.error&&<Alert variant="destructive"><AlertTriangle/><AlertTitle>Falha na importação</AlertTitle><AlertDescription>{detail.summary.error}</AlertDescription></Alert>}<ListaErros resumo={detail.summary}/></div>}<DialogFooter><Button variant="outline" onClick={()=>setDetail(null)}>Fechar</Button></DialogFooter></DialogContent></Dialog></>}

const ticketStatusMap:AnyRow={aberto:['Aberto','bg-sky-50 text-sky-700 ring-1 ring-sky-200'],aguardando_fornecedor:['Aguardando fornecedor','bg-violet-50 text-violet-700 ring-1 ring-violet-200'],fechado:['Fechado','bg-emerald-50 text-emerald-700 ring-1 ring-emerald-200'],cancelado:['Cancelado','bg-slate-100 text-slate-600 ring-1 ring-slate-200']};
const priorityMap:AnyRow={alta:['Alta','bg-red-50 text-red-700'],media:['Média','bg-amber-50 text-amber-700'],baixa:['Baixa','bg-slate-100 text-slate-600']};
function tempoEmAberto(criadoEm:string,fechadoEm?:string|null){
  const inicio=new Date(criadoEm).getTime(), fim=fechadoEm?new Date(fechadoEm).getTime():Date.now();
  const ms=Math.max(fim-inicio,0), horas=Math.floor(ms/3600000), dias=Math.floor(horas/24);
  const rotulo=dias>=1?`${dias}d ${horas%24}h`:horas>=1?`${horas}h ${Math.floor((ms%3600000)/60000)}min`:`${Math.floor(ms/60000)}min`;
  return {dias,horas,rotulo,encerrado:!!fechadoEm};
}
function Sla({createdAt,closedAt}:JsonData){
  const t=tempoEmAberto(createdAt,closedAt);
  if(t.encerrado) return <div><p className="font-medium tabular-nums">{t.rotulo}</p><p className="text-[11px] text-muted-foreground">até o encerramento</p></div>;
  const tom=t.dias>=15?'text-red-700':t.dias>=7?'text-amber-700':'text-foreground';
  const aviso=t.dias>=15?'acima de 15 dias':t.dias>=7?'acima de 7 dias':'em andamento';
  return <div><p className={`font-semibold tabular-nums ${tom}`}>{t.rotulo}</p><p className={`text-[11px] ${t.dias>=7?tom:'text-muted-foreground'}`}>{aviso}</p></div>;
}
function TicketStatus({value}:JsonData){const x=ticketStatusMap[value]||[value,'bg-slate-100'];return <Badge className={x[1]}>{x[0]}</Badge>}

function Tickets({users,run,refreshCounts,initialDetail}:JsonData){
  const [data,setData]=useState<AnyRow|null>(null),[statuses,setStatuses]=useState<string[]>([]),[sortBy,setSortBy]=useState('updatedAt'),[sortDirection,setSortDirection]=useState('desc'),[q,setQ]=useState(''),[open,setOpen]=useState<AnyRow|null>(null),[detail,setDetail]=useState<string|null>(initialDetail||null);
  const load=useCallback(()=>api('/api/tickets').then(x=>{setData(x);refreshCounts?.(x.stats?.total)}),[refreshCounts]);
  useEffect(()=>{void load()},[load]);
  if(!data) return <Loading label="Carregando chamados…"/>;
  if(detail) return <TicketDetail id={detail} onBack={()=>{setDetail(null);void load()}} run={run}/>;
  const s=data.stats||{};
  const prioridade:AnyRow={alta:1,media:2,baixa:3};
  const valorOrdenacao=(r:AnyRow)=>sortBy==='code'?Number(String(r.code).replace(/\D/g,'')):sortBy==='priority'?prioridade[r.priority]||9:sortBy==='openTime'?Date.parse(r.closedAt||new Date().toISOString())-Date.parse(r.createdAt):sortBy==='updatedAt'?Date.parse(r.updatedAt):String(r[sortBy]||'');
  const rows=(data.tickets||[]).filter((r:AnyRow)=>(!statuses.length||statuses.includes(r.status))&&(!q||correspondeBusca(`${r.code} ${r.supplierName} ${r.city}`,q))).sort((a:AnyRow,b:AnyRow)=>{const av=valorOrdenacao(a),bv=valorOrdenacao(b);const result=typeof av==='number'&&typeof bv==='number'?av-bv:String(av).localeCompare(String(bv),'pt-BR',{sensitivity:'base'});return sortDirection==='asc'?result:-result});
  const cards=[['Abertos',s.aberto,'from-sky-500/10 to-sky-500/0 text-sky-700'],['Aguardando',s.aguardando,'from-violet-500/10 to-violet-500/0 text-violet-700'],['Fechados',s.fechado,'from-emerald-500/10 to-emerald-500/0 text-emerald-700']];
  const toggleStatus=(value:string)=>setStatuses(current=>current.includes(value)?current.filter(x=>x!==value):[...current,value]);
  return <div className="space-y-6">
    <section className="grid gap-3 sm:grid-cols-3">{cards.map(([label,value,tone]:JsonData,i:number)=><Card key={label} className="overflow-hidden shadow-sm animate-in fade-in slide-in-from-bottom-2 fill-mode-both" style={{animationDelay:`${i*60}ms`}}><CardContent className={`bg-gradient-to-br ${tone}`}><p className="text-sm font-medium text-muted-foreground">{label}</p><p className="mt-2 text-4xl font-semibold tabular-nums tracking-[-.045em]">{Number(value||0)}</p></CardContent></Card>)}</section>
    <div className="flex flex-wrap gap-3">
      <div className="relative min-w-64 flex-1"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground"/><Input className="pl-9" placeholder="Código, fornecedor ou cidade" value={q} onChange={e=>setQ(e.target.value)}/></div>
      <details className="group relative"><summary className="flex h-9 min-w-52 cursor-pointer list-none items-center justify-between rounded-md border bg-background px-3 text-sm shadow-xs marker:content-none">{statuses.length?`${statuses.length} situação(ões)`: 'Todas as situações'}<span className="ml-3 text-muted-foreground group-open:rotate-180">⌄</span></summary><div className="absolute right-0 z-20 mt-2 min-w-64 rounded-xl border bg-popover p-2 shadow-lg">{Object.entries(ticketStatusMap).map(([k,v]:JsonData)=><label key={k} className="flex cursor-pointer items-center gap-3 rounded-lg px-2 py-2 text-sm hover:bg-muted"><Checkbox checked={statuses.includes(k)} onCheckedChange={()=>toggleStatus(k)}/><span>{v[0]}</span></label>)}{statuses.length?<Button variant="ghost" size="sm" className="mt-1 w-full text-muted-foreground" onClick={()=>setStatuses([])}>Limpar seleção</Button>:null}</div></details>
      <NativeSelect className="w-44" aria-label="Ordenar chamados por" value={sortBy} onChange={e=>setSortBy(e.target.value)}><NativeSelectOption value="updatedAt">Atualização</NativeSelectOption><NativeSelectOption value="code">Código</NativeSelectOption><NativeSelectOption value="supplierName">Fornecedor</NativeSelectOption><NativeSelectOption value="city">Cidade</NativeSelectOption><NativeSelectOption value="priority">Prioridade</NativeSelectOption><NativeSelectOption value="status">Situação</NativeSelectOption><NativeSelectOption value="openTime">Em aberto</NativeSelectOption><NativeSelectOption value="requestedBy">Solicitante</NativeSelectOption></NativeSelect>
      <NativeSelect className="w-36" aria-label="Direção da ordenação" value={sortDirection} onChange={e=>setSortDirection(e.target.value)}><NativeSelectOption value="asc">Crescente</NativeSelectOption><NativeSelectOption value="desc">Decrescente</NativeSelectOption></NativeSelect>
      <Button onClick={()=>setOpen({priority:'media'})}><Plus/> Novo chamado</Button>
    </div>
    {rows.length?<Card><CardHeader className="border-b"><CardTitle>{rows.length} chamado(s)</CardTitle></CardHeader><CardContent className="px-0 pb-0"><Table><TableHeader><TableRow><TableHead>Código</TableHead><TableHead>Fornecedor</TableHead><TableHead>Local</TableHead><TableHead>Prioridade</TableHead><TableHead>Situação</TableHead><TableHead>Em aberto</TableHead><TableHead>Solicitante</TableHead><TableHead>Atualizado</TableHead></TableRow></TableHeader><TableBody>{rows.map((r:AnyRow)=><TableRow key={r.id}><TableCell><button className="text-left" onClick={()=>setDetail(r.id)}><span className="block font-mono text-xs font-semibold text-primary hover:underline">{r.code}</span></button></TableCell><TableCell className="font-medium">{r.supplierName}{r.cnpj?<p className="text-xs font-normal text-muted-foreground">{cnpj(r.cnpj)}</p>:null}</TableCell><TableCell>{r.city?`${r.city} / ${r.state||''}`:'—'}</TableCell><TableCell><Badge className={(priorityMap[r.priority]||['—','bg-slate-100'])[1]}>{(priorityMap[r.priority]||['—'])[0]}</Badge></TableCell><TableCell><TicketStatus value={r.status}/></TableCell><TableCell className="text-sm"><Sla createdAt={r.createdAt} closedAt={r.closedAt}/></TableCell><TableCell className="text-sm">{r.requestedBy||'—'}</TableCell><TableCell className="text-sm text-muted-foreground">{new Date(r.updatedAt).toLocaleDateString('pt-BR')}</TableCell></TableRow>)}</TableBody></Table></CardContent></Card>:<Empty icon={MessageSquare} title="Nenhum chamado" text="Abra um chamado para registrar um fornecedor que precisa ser negociado."/>}
    {open&&<TicketDialog open value={open} users={users} onClose={()=>setOpen(null)} onSave={(body:AnyRow)=>run(async()=>{await api('/api/tickets',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});setOpen(null);await load()},'Chamado aberto.')}/>}
  </div>;
}

function TicketDetail({id,onBack,run}:JsonData){
  const [d,setD]=useState<AnyRow|null>(null),[msg,setMsg]=useState(''),[status,setStatus]=useState(''),[statusMessage,setStatusMessage]=useState('');
  const load=useCallback(()=>api(`/api/tickets/${id}`).then(x=>{setD(x);setStatus(x.ticket.status);setStatusMessage('')}),[id]);
  useEffect(()=>{void load()},[load]);
  if(!d) return <Loading label="Abrindo chamado…"/>;
  const t=d.ticket;
  return <div className="space-y-5">
    <div className="flex flex-wrap items-center gap-3"><Button variant="outline" onClick={onBack}>← Voltar</Button><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h2 className="truncate text-2xl font-semibold tracking-[-.02em]">{t.supplier_name}</h2><TicketStatus value={t.status}/><Badge className={(priorityMap[t.priority]||['—','bg-slate-100'])[1]}>{(priorityMap[t.priority]||['—'])[0]}</Badge></div><p className="text-sm text-muted-foreground font-mono">{t.code}{t.cnpj?` · ${cnpj(t.cnpj)}`:''}</p></div></div>
    <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Info label="Solicitante" value={t.requestedBy||'—'}/><Info label="Responsável" value={t.assignedTo||'Não atribuído'}/><Info label="Aberto em" value={new Date(t.created_at).toLocaleDateString('pt-BR')}/><Card size="sm"><CardContent><p className="text-xs text-muted-foreground">{t.closed_at?'Tempo até encerrar':'Tempo em aberto'}</p><div className="mt-1"><Sla createdAt={t.created_at} closedAt={t.closed_at}/></div></CardContent></Card><Info label="Local" value={t.city?`${t.city} / ${t.state||''}`:'—'}/></section>
    {(t.scope||t.contact||t.notes)&&<Card><CardContent className="space-y-3 pt-5 text-sm">{t.scope&&<div><p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Escopo</p><p className="mt-1">{t.scope}</p></div>}{t.contact&&<div><p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Contato</p><p className="mt-1">{t.contact}</p></div>}{t.notes&&<div><p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Observações</p><p className="mt-1 whitespace-pre-wrap">{t.notes}</p></div>}</CardContent></Card>}
    <Card><CardHeader className="border-b"><CardTitle>Situação</CardTitle></CardHeader><CardContent className="grid gap-3 pt-4 sm:grid-cols-[minmax(14rem,.6fr)_1fr_auto] sm:items-end"><SelectField label="Alterar para" value={status} onChange={setStatus} rows={Object.entries(ticketStatusMap).map(([k,v]:JsonData)=>({id:k,name:v[0]}))}/><Field label={(status==='fechado'||status==='cancelado')?'Resultado ou motivo *':'Mensagem da alteração'}><Input placeholder="Informe o que motivou esta mudança" value={statusMessage} onChange={e=>setStatusMessage(e.target.value)}/></Field><Button disabled={status===t.status||((status==='fechado'||status==='cancelado')&&!statusMessage.trim())} onClick={()=>run(async()=>{await api(`/api/tickets/${id}`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({status,statusMessage})});await load()},'Situação atualizada.')}><RefreshCw/> Aplicar</Button></CardContent></Card>
    <Card><CardHeader className="border-b"><CardTitle>Histórico e progresso</CardTitle><p className="mt-1 text-sm text-muted-foreground">{d.events.length} registro(s) neste chamado.</p></CardHeader><CardContent className="pt-5">
      <ol className="relative space-y-5 border-l border-dashed pl-6">{d.events.map((e:AnyRow)=><li key={e.id} className="relative animate-in fade-in slide-in-from-left-2 fill-mode-both"><span className={`absolute -left-[31px] grid size-5 place-items-center rounded-full ring-4 ring-background ${e.kind==='status'?'bg-amber-500':e.kind==='created'?'bg-teal-500':'bg-slate-300'}`}/><div className="flex flex-wrap items-baseline gap-2"><span className="text-sm font-semibold">{e.user||'Sistema'}</span><span className="text-xs text-muted-foreground">{new Date(e.createdAt).toLocaleString('pt-BR')}</span></div>{e.kind==='status'?<p className="mt-1 text-sm">Situação alterada de <b>{(ticketStatusMap[e.fromStatus]||[e.fromStatus])[0]}</b> para <b>{(ticketStatusMap[e.toStatus]||[e.toStatus])[0]}</b>.</p>:<p className="mt-1 whitespace-pre-wrap text-sm">{e.message}</p>}</li>)}</ol>
      <div className="mt-6 space-y-3 border-t pt-5"><Field label="Registrar andamento"><Textarea placeholder="O que aconteceu na tratativa?" value={msg} onChange={e=>setMsg(e.target.value)}/></Field><div className="flex justify-end"><Button disabled={!msg.trim()} onClick={()=>run(async()=>{await api(`/api/tickets/${id}/events`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({message:msg})});setMsg('');await load()},'Andamento registrado.')}><Plus/> Adicionar</Button></div></div>
    </CardContent></Card>
  </div>;
}

function TicketDialog({open,value,users,onClose,onSave}:JsonData){const [form,setForm]=useState<AnyRow>(value||{priority:'media'});return <Dialog open={open} onOpenChange={(x)=>!x&&onClose()}><DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-2xl"><DialogHeader><DialogTitle>Novo chamado de negociação</DialogTitle><DialogDescription>Registre o fornecedor com quem devemos tentar fechar acordo.</DialogDescription></DialogHeader><div className="grid gap-4 sm:grid-cols-2"><Field label="Fornecedor *" className="sm:col-span-2"><Input value={form.supplierName||''} onChange={e=>setForm({...form,supplierName:e.target.value})}/></Field><Field label="CNPJ"><Input value={form.cnpj||''} onChange={e=>setForm({...form,cnpj:e.target.value})}/></Field><Field label="Contato"><Input placeholder="Nome, telefone ou e-mail" value={form.contact||''} onChange={e=>setForm({...form,contact:e.target.value})}/></Field><Field label="Cidade"><Input value={form.city||''} onChange={e=>setForm({...form,city:e.target.value})}/></Field><Field label="UF"><Input maxLength={2} value={form.state||''} onChange={e=>setForm({...form,state:e.target.value.toUpperCase()})}/></Field><SelectField label="Prioridade" value={form.priority||'media'} onChange={(v:string)=>setForm({...form,priority:v})} rows={[{id:'alta',name:'Alta'},{id:'media',name:'Média'},{id:'baixa',name:'Baixa'}]}/><SelectField label="Responsável" value={form.assignedTo||''} onChange={(v:string)=>setForm({...form,assignedTo:v})} rows={users||[]}/><Field label="Escopo pretendido" className="sm:col-span-2"><Input placeholder="Ex.: pneus e alinhamento para a frota leve" value={form.scope||''} onChange={e=>setForm({...form,scope:e.target.value})}/></Field><Field label="Observações" className="sm:col-span-2"><Textarea value={form.notes||''} onChange={e=>setForm({...form,notes:e.target.value})}/></Field></div><DialogFooter><Button variant="outline" onClick={onClose}>Cancelar</Button><Button disabled={!form.supplierName} onClick={()=>onSave(form)}><CheckCircle2/> Abrir chamado</Button></DialogFooter></DialogContent></Dialog>}

function ChangeHistory({users}:JsonData){
  const [logs,setLogs]=useState<AnyRow[]>([]),[meta,setMeta]=useState<AnyRow>({page:1,pageCount:1,total:0}),[page,setPage]=useState(1),[loading,setLoading]=useState(true),[recarregar,setRecarregar]=useState(0),[erro,setErro]=useState(''),[f,setFiltros]=useState({user:'',action:'',entity:'',q:'',from:'',to:''});
  const setF=(next:AnyRow)=>{setFiltros(next as never);setPage(1)};
  useEffect(()=>{
    // Flag local por execucao do efeito. Trocar de pagina rapido dispara varias
    // consultas: sem isto, uma resposta lenta sobrescreveria outra mais nova.
    // O cleanup desliga a flag, o que tambem cobre o componente sair da tela
    // antes de a resposta chegar.
    let ativa=true;
    // setState direto no corpo do efeito dispara renderizacao em cascata; o
    // microtask adia para depois do efeito e mantem o indicador de carregando.
    queueMicrotask(()=>{ if(ativa){setLoading(true);setErro('')} });
    const p=new URLSearchParams(Object.entries(f).filter(([,v])=>v));
    p.set('page',String(page));p.set('pageSize','50');
    void api(`/api/audit?${p}`).then((result:AnyRow)=>{
      if(!ativa)return; // resposta superada: descarta
      setLogs(result.logs);
      setMeta({page:result.page,pageCount:result.pageCount,total:result.total,pageSize:result.pageSize});
    }).catch((e:unknown)=>{
      // Sem este catch, uma indisponibilidade momentanea do servidor virava
      // rejeicao sem tratamento e a tela ficava carregando para sempre.
      if(!ativa)return;
      setErro(e instanceof Error?e.message:'Não foi possível carregar o histórico.');
      setLogs([]);
    }).finally(()=>{ if(ativa) setLoading(false); });
    // Invalida esta consulta se o componente sair da tela antes da resposta.
    return ()=>{ativa=false};
  },[f,page,recarregar]);
  const load=()=>setRecarregar((n)=>n+1);
  const actionTone=(a:string)=>a==='CREATE'?'bg-emerald-50 text-emerald-700':a==='DELETE'?'bg-red-50 text-red-700':a==='IMPORT'?'bg-violet-50 text-violet-700':a==='LOGIN'?'bg-slate-100 text-slate-600':'bg-sky-50 text-sky-700';
  const entityName=(e:string)=>({agreement:'Acordo',agreement_item:'Condição',ticket:'Chamado',user:'Usuário',session:'Sessão',system:'Sistema',legacy_base:'Carga inicial',suppliers:'Fornecedor',items:'Item',models:'Modelo',units:'Unidade',brands:'Marca',locations:'Localidade'} as AnyRow)[e]||e;
  return <div className="space-y-5">
    <Card><CardHeader><CardTitle>Filtros</CardTitle></CardHeader><CardContent className="grid gap-3 md:grid-cols-2 xl:grid-cols-6">
      <Field label="Busca" className="xl:col-span-2"><Input placeholder="Detalhe, registro ou usuário" value={f.q} onChange={e=>setF({...f,q:e.target.value})}/></Field>
      <SelectField label="Usuário" value={f.user} onChange={(v:string)=>setF({...f,user:v})} rows={users||[]}/>
      <SelectField label="Ação" value={f.action} onChange={(v:string)=>setF({...f,action:v})} rows={[{id:'CREATE',name:'Criação'},{id:'UPDATE',name:'Alteração'},{id:'DELETE',name:'Exclusão'},{id:'UPSERT',name:'Inclusão em lote'},{id:'IMPORT',name:'Importação'},{id:'COMMENT',name:'Andamento'},{id:'LOGIN',name:'Acesso'}]}/>
      <Field label="De"><Input type="date" value={f.from} onChange={e=>setF({...f,from:e.target.value})}/></Field>
      <Field label="Até"><Input type="date" value={f.to} onChange={e=>setF({...f,to:e.target.value})}/></Field>
    </CardContent></Card>
    <Card><CardHeader className="border-b sm:grid-cols-[1fr_auto]"><div><CardTitle>{loading?'Carregando…':`${Number(meta.total||0).toLocaleString('pt-BR')} modificação(ões)`}</CardTitle><p className="mt-1 text-sm text-muted-foreground">{meta.total?`Mostrando ${((meta.page-1)*meta.pageSize)+1}–${Math.min(meta.page*meta.pageSize,meta.total)} · página ${meta.page} de ${meta.pageCount}`:'Mais recentes primeiro.'}</p></div><Button variant="outline" onClick={load}><RefreshCw/> Atualizar</Button></CardHeader><CardContent className="max-h-[64vh] overflow-auto px-0 pb-0"><Table><TableHeader className="sticky top-0 z-10 bg-card"><TableRow><TableHead>Quando</TableHead><TableHead>Usuário</TableHead><TableHead>Ação</TableHead><TableHead>Registro</TableHead><TableHead>Detalhes</TableHead></TableRow></TableHeader><TableBody>{logs.map(r=><TableRow key={r.id}><TableCell className="whitespace-nowrap text-sm tabular-nums">{new Date(r.createdAt).toLocaleString('pt-BR')}</TableCell><TableCell><p className="text-sm font-medium">{r.user||'Sistema'}</p><p className="text-[11px] text-muted-foreground">{r.userEmail||''}</p></TableCell><TableCell><Badge className={actionTone(r.action)}>{r.action}</Badge></TableCell><TableCell className="text-sm">{entityName(r.entity)}</TableCell><TableCell className="max-w-[28rem] text-sm text-muted-foreground">{r.details}</TableCell></TableRow>)}</TableBody></Table>{!loading&&erro&&<div className="p-8"><Alert variant="destructive"><AlertTriangle/><AlertTitle>Não foi possível carregar o histórico</AlertTitle><AlertDescription><p>{erro}</p><Button className="mt-3" size="sm" variant="outline" onClick={load}><RefreshCw/> Tentar de novo</Button></AlertDescription></Alert></div>}{!loading&&!erro&&!logs.length&&<div className="p-10 text-center text-sm text-muted-foreground">Nenhuma modificação com esses filtros.</div>}</CardContent>{meta.pageCount>1&&<div className="flex flex-wrap items-center justify-between gap-3 border-t px-5 py-3"><p className="text-sm text-muted-foreground">Página <b className="text-foreground">{meta.page}</b> de {meta.pageCount}</p><div className="flex items-center gap-1"><Button size="sm" variant="outline" disabled={loading||meta.page<=1} onClick={()=>setPage(1)}>Primeira</Button><Button size="sm" variant="outline" disabled={loading||meta.page<=1} onClick={()=>setPage(meta.page-1)}>← Anterior</Button><Button size="sm" variant="outline" disabled={loading||meta.page>=meta.pageCount} onClick={()=>setPage(meta.page+1)}>Próxima →</Button><Button size="sm" variant="outline" disabled={loading||meta.page>=meta.pageCount} onClick={()=>setPage(meta.pageCount)}>Última</Button></div></div>}</Card>
  </div>;
}

function EmailQueue({run}:JsonData){
  const [data,setData]=useState<AnyRow|null>(null),[error,setError]=useState('');
  const load=useCallback(()=>api('/api/email-notifications').then(setData).catch((e:unknown)=>setError(errorText(e))),[]);
  useEffect(()=>{void load()},[load]);
  const statusEmail:AnyRow={pending:['Pendente','bg-amber-50 text-amber-700'],processing:['Enviando','bg-sky-50 text-sky-700'],sent:['Enviado','bg-emerald-50 text-emerald-700'],failed:['Falhou','bg-red-50 text-red-700']};
  const tipoEmail:AnyRow={atribuicao:'Atribuição',atualizacao:'Atualização',conclusao:'Conclusão',cancelamento:'Cancelamento'};
  if(error)return <Alert variant="destructive" className="mt-5"><AlertTriangle/><AlertTitle>Não foi possível consultar os e-mails</AlertTitle><AlertDescription>{error}</AlertDescription></Alert>;
  if(!data)return <Card className="mt-5"><CardContent className="flex items-center gap-3 py-5"><LoaderCircle className="size-4 animate-spin"/> Carregando envios de e-mail…</CardContent></Card>;
  const s=data.stats||{};
  return <Card className="mt-5"><CardHeader className="border-b"><div className="flex flex-wrap items-center justify-between gap-3"><div><CardTitle>Notificações por e-mail</CardTitle><p className="mt-1 text-sm text-muted-foreground">{Number(s.pending||0)} pendente(s), {Number(s.failed||0)} falha(s) e {Number(s.sent||0)} enviada(s).</p></div><Button variant="outline" onClick={()=>void load()}><RefreshCw/> Atualizar</Button></div></CardHeader><CardContent className="px-0 pb-0">{data.notifications?.length?<Table><TableHeader><TableRow><TableHead>Chamado</TableHead><TableHead>Tipo</TableHead><TableHead>Destinatário</TableHead><TableHead>Situação</TableHead><TableHead>Tentativas</TableHead><TableHead>Data</TableHead><TableHead/></TableRow></TableHeader><TableBody>{data.notifications.map((item:AnyRow)=>{const st=statusEmail[item.status]||[item.status,'bg-slate-100'];return <TableRow key={item.id}><TableCell><p className="font-mono text-xs font-semibold">{item.ticketCode}</p><p className="text-xs text-muted-foreground">{item.supplierName}</p></TableCell><TableCell>{tipoEmail[item.type]||item.type}</TableCell><TableCell><p>{item.recipientName}</p><p className="text-xs text-muted-foreground">{item.recipientEmail}</p></TableCell><TableCell><Badge className={st[1]}>{st[0]}</Badge>{item.lastError?<p className="mt-1 max-w-80 truncate text-xs text-red-700" title={item.lastError}>{item.lastError}</p>:null}</TableCell><TableCell>{item.attempts}</TableCell><TableCell className="text-xs text-muted-foreground">{new Date(item.sentAt||item.nextAttemptAt||item.createdAt).toLocaleString('pt-BR')}</TableCell><TableCell className="text-right">{item.status==='failed'&&<Button size="sm" variant="outline" onClick={()=>void run(async()=>{await api(`/api/email-notifications/${item.id}/retry`,{method:'POST'});await load()},'Reenvio colocado na fila.')}><RefreshCw/> Reenviar</Button>}</TableCell></TableRow>})}</TableBody></Table>:<div className="py-10 text-center text-sm text-muted-foreground">Nenhuma notificação foi criada ainda.</div>}</CardContent></Card>;
}

function Administration({user,initialUsers,run}:JsonData){const [users,setUsers]=useState<AnyRow[]>(initialUsers||[]),[open,setOpen]=useState(false),[edit,setEdit]=useState<AnyRow|null>(null);const load=useCallback(async()=>{const result=await api('/api/users');setUsers(result.users)},[]);const isAdmin=user.role==='admin';return <div className="space-y-5"><div className="flex flex-wrap justify-between gap-3"><p className="text-sm text-muted-foreground">{users.length} conta(s) · o histórico completo de alterações fica na aba <b>Histórico</b>.</p><div className="flex gap-2"><Button variant="outline" onClick={()=>window.open('/api/export','_blank','noopener,noreferrer')}><Download/> Exportar dados</Button>{isAdmin&&<Button onClick={()=>setOpen(true)}><Plus/> Novo usuário</Button>}</div></div><Card><CardContent className="px-0 pb-0"><Table><TableHeader><TableRow><TableHead>Nome</TableHead><TableHead>E-mail</TableHead><TableHead>Perfil</TableHead><TableHead>Relatório diário</TableHead><TableHead>Situação</TableHead><TableHead/></TableRow></TableHeader><TableBody>{users.map(r=><TableRow key={r.id} className={r.active?'':'opacity-50'}><TableCell className="font-medium">{r.name}{r.id===user.id?<Badge className="ml-2 bg-teal-50 text-teal-700">você</Badge>:null}</TableCell><TableCell className="text-sm">{r.email}</TableCell><TableCell><Badge className={r.role==='admin'?'bg-violet-50 text-violet-700':r.role==='editor'?'bg-sky-50 text-sky-700':'bg-slate-100 text-slate-600'}>{roleName(r.role)}</Badge></TableCell><TableCell>{r.dailyReportEnabled?<span className="text-sm font-medium">Diariamente às {r.dailyReportTime}</span>:<span className="text-sm text-muted-foreground">Não recebe</span>}</TableCell><TableCell><Badge className={r.active?'bg-emerald-50 text-emerald-700':'bg-slate-100 text-slate-600'}>{r.active?'Ativo':'Inativo'}</Badge></TableCell><TableCell className="text-right">{isAdmin&&<Button size="icon-sm" variant="ghost" onClick={()=>setEdit({...r})}><Pencil/></Button>}</TableCell></TableRow>)}</TableBody></Table></CardContent></Card><UserDialog open={open} onClose={()=>setOpen(false)} onSave={(body:AnyRow)=>run(async()=>{await api('/api/users',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});setOpen(false);await load()},'Usuário criado.')}/>{edit&&<UserEditDialog open value={edit} self={user} onClose={()=>setEdit(null)} onSave={(body:AnyRow)=>run(async()=>{await api(`/api/users/${body.id}`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(body)});setEdit(null);await load()},'Usuário atualizado.')}/>}</div>}

function UserEditDialog({open,value,self,onClose,onSave}:JsonData){const [form,setForm]=useState<AnyRow>({...value,password:''});const isSelf=value.id===self.id;return <Dialog open={open} onOpenChange={(x)=>!x&&onClose()}><DialogContent><DialogHeader><DialogTitle>Editar usuário</DialogTitle><DialogDescription>{value.email}</DialogDescription></DialogHeader><div className="space-y-4"><Field label="Nome"><Input value={form.name||''} onChange={e=>setForm({...form,name:e.target.value})}/></Field><SelectField label="Perfil" value={form.role||'viewer'} onChange={(v:string)=>setForm({...form,role:v})} rows={[{id:'viewer',name:'Consulta'},{id:'editor',name:'Comprador'},{id:'admin',name:'Administrador'}]}/><Field label="Nova senha"><Input type="password" placeholder="Deixe em branco para manter a atual" value={form.password||''} onChange={e=>setForm({...form,password:e.target.value})}/><p className="mt-1 text-xs text-muted-foreground">Ao redefinir, as sessões abertas deste usuário são encerradas.</p></Field><div className="rounded-lg border p-3"><div className="flex items-center gap-2"><Checkbox id="daily-report-enabled" checked={!!form.dailyReportEnabled} onCheckedChange={(c:JsonData)=>setForm({...form,dailyReportEnabled:!!c})}/><label htmlFor="daily-report-enabled" className="cursor-pointer text-sm font-medium">Receber relatório diário de chamados</label></div>{form.dailyReportEnabled?<Field label="Horário de envio" className="mt-3"><Input type="time" value={form.dailyReportTime||'17:45'} onChange={e=>setForm({...form,dailyReportTime:e.target.value})}/></Field>:null}</div><label className="flex cursor-pointer items-center gap-2 rounded-lg border p-3"><Checkbox checked={form.active!==false&&form.active!==0} onCheckedChange={(c:JsonData)=>setForm({...form,active:!!c})} disabled={isSelf}/><span className="text-sm">Conta ativa{isSelf?' (não é possível desativar a própria conta)':''}</span></label></div><DialogFooter><Button variant="outline" onClick={onClose}>Cancelar</Button><Button onClick={()=>onSave(form)}><CheckCircle2/> Salvar</Button></DialogFooter></DialogContent></Dialog>}

function AgreementDialog({open,value,catalogs,busy,onClose,onSave}:JsonData){const [form,setForm]=useState<AnyRow>(value||{});const toggle=(recordId:string)=>setForm({...form,locationIds:(form.locationIds||[]).includes(recordId)?form.locationIds.filter((x:string)=>x!==recordId):[...(form.locationIds||[]),recordId]});return <Dialog open={open} onOpenChange={(x)=>!x&&onClose()}><DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-3xl"><DialogHeader><DialogTitle>{form.id?'Editar acordo':'Novo acordo'}</DialogTitle><DialogDescription>Preencha a identificação, o fornecedor, a vigência e as localidades abrangidas.</DialogDescription></DialogHeader><div className="grid gap-4 sm:grid-cols-2"><Field label="Número do acordo *"><Input value={form.number||''} onChange={e=>setForm({...form,number:e.target.value})}/></Field><SelectField label="Fornecedor / CNPJ *" value={form.supplierId||''} onChange={(v:string)=>setForm({...form,supplierId:v})} rows={catalogs.suppliers} labelFn={(x:AnyRow)=>`${x.tradeName} · ${cnpj(x.cnpj)}`}/><Field label="Início da vigência *"><Input type="date" value={form.startDate||''} onChange={e=>setForm({...form,startDate:e.target.value})}/></Field><Field label="Fim da vigência"><Input type="date" value={form.endDate||''} onChange={e=>setForm({...form,endDate:e.target.value})}/></Field><SelectField label="Situação" value={form.status||'active'} onChange={(v:string)=>setForm({...form,status:v})} rows={[{id:'active',name:'Vigente'},{id:'suspended',name:'Suspenso'}]}/><Field label=""><p className="text-xs text-muted-foreground">Um acordo passa a <b>Expirado</b> sozinho quando a data de fim vence.</p></Field><div/><div className="sm:col-span-2"><p className="mb-2 text-sm font-medium">Localidades abrangidas *</p><div className="grid max-h-48 gap-2 overflow-y-auto rounded-xl border p-3 sm:grid-cols-2">{catalogs.locations.map((x:AnyRow)=><label key={x.id} className="flex cursor-pointer items-center gap-2 rounded-lg p-2 hover:bg-muted"><Checkbox checked={(form.locationIds||[]).includes(x.id)} onCheckedChange={()=>toggle(x.id)}/><span>{x.city} / {x.state}</span></label>)}</div></div><Field label="Observações" className="sm:col-span-2"><Textarea value={form.notes||''} onChange={e=>setForm({...form,notes:e.target.value})}/></Field></div><DialogFooter><Button variant="outline" onClick={onClose}>Cancelar</Button><Button disabled={busy||!form.number||!form.supplierId||!form.startDate||!(form.locationIds||[]).length} onClick={()=>onSave(form)}>{busy?<LoaderCircle className="animate-spin"/>:<CheckCircle2/>} Salvar acordo</Button></DialogFooter></DialogContent></Dialog>}
function ItemDialog({open,value,catalogs,busy,onClose,onSave}:JsonData){const [form,setForm]=useState<AnyRow>(value||{});const editing=!!form.id;const toggle=(recordId:string)=>setForm({...form,modelIds:(form.modelIds||[]).includes(recordId)?form.modelIds.filter((x:string)=>x!==recordId):[...(form.modelIds||[]),recordId]});return <Dialog open={open} onOpenChange={(x)=>!x&&onClose()}><DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-3xl"><DialogHeader><DialogTitle>{editing?'Editar condição':'Nova condição acordada'}</DialogTitle><DialogDescription>Um mesmo item pode ser aplicado a vários modelos com o mesmo preço.</DialogDescription></DialogHeader><div className="grid gap-4 sm:grid-cols-2"><SelectField label="Peça ou serviço *" value={form.catalogItemId||''} onChange={(v:string)=>setForm({...form,catalogItemId:v})} rows={catalogs.items}/><SelectField label="Localidade *" value={form.locationId||''} onChange={(v:string)=>setForm({...form,locationId:v})} rows={catalogs.locations} labelFn={(x:AnyRow)=>`${x.city} / ${x.state}`}/><Field label="Preço *"><Input type="number" min="0" step="0.01" value={form.price??''} onChange={e=>setForm({...form,price:e.target.value})}/><p className="mt-1 text-xs text-muted-foreground">Use zero para cortesia.</p></Field><SelectField label="Unidade *" value={form.unitId||''} onChange={(v:string)=>setForm({...form,unitId:v})} rows={catalogs.units} labelFn={(x:AnyRow)=>`${x.code} · ${x.name}`}/><div className="sm:col-span-2"><p className="mb-2 text-sm font-medium">{editing?'Modelo *':'Modelos aplicáveis *'}</p>{editing?<NativeSelect className="w-full" value={form.modelId||''} onChange={e=>setForm({...form,modelId:e.target.value})}><NativeSelectOption value="">Selecione</NativeSelectOption>{catalogs.models.map((x:AnyRow)=><NativeSelectOption key={x.id} value={x.id}>{x.name}</NativeSelectOption>)}</NativeSelect>:<div className="grid max-h-44 gap-2 overflow-y-auto rounded-xl border p-3 sm:grid-cols-2">{catalogs.models.map((x:AnyRow)=><label key={x.id} className="flex cursor-pointer items-center gap-2 rounded-lg p-2 hover:bg-muted"><Checkbox checked={(form.modelIds||[]).includes(x.id)} onCheckedChange={()=>toggle(x.id)}/><span>{x.name}</span></label>)}</div>}</div><Field label="Marcas aceitas" className="sm:col-span-2"><Input placeholder="Ex.: BOSCH / FRASLE / TRW" value={form.brands||''} onChange={e=>setForm({...form,brands:e.target.value})}/></Field><Field label="Observações" className="sm:col-span-2"><Textarea value={form.notes||''} onChange={e=>setForm({...form,notes:e.target.value})}/></Field></div><DialogFooter><Button variant="outline" onClick={onClose}>Cancelar</Button><Button disabled={busy||!form.catalogItemId||!form.locationId||!form.unitId||(editing?!form.modelId:!(form.modelIds||[]).length)||form.price===''} onClick={()=>onSave(form)}>{busy?<LoaderCircle className="animate-spin"/>:<CheckCircle2/>} Salvar condição</Button></DialogFooter></DialogContent></Dialog>}

function Mappings({catalogs,run}:JsonData){
  const [data,setData]=useState<AnyRow>({items:[],models:[]}),[type,setType]=useState<'items'|'models'>('items'),[edit,setEdit]=useState<AnyRow|null>(null),[loading,setLoading]=useState(true);
  const load=useCallback(async()=>{setData(await api('/api/mappings'))},[]);
  useEffect(()=>{let active=true;void api('/api/mappings').then(result=>{if(active){setData(result);setLoading(false)}});return()=>{active=false}},[]);
  const rows=data[type]||[], targets=type==='items'?catalogs.items:catalogs.models;
  const remove=(row:AnyRow)=>{if(!confirm(`Excluir a correspondência "${row.source}"?`))return;void run(async()=>{await api(`/api/mappings/${type}/${row.id}`,{method:'DELETE'});await load()},'Correspondência excluída.')};
  return <div className="space-y-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><h1 className="text-2xl font-semibold">De/Para da importação</h1><p className="mt-1 text-sm text-muted-foreground">Toda nomenclatura de item e modelo da planilha precisa ter uma correspondência ativa. As unidades são validadas no cadastro de unidades.</p></div><Button onClick={()=>setEdit({type,active:true})}><Plus/> Nova correspondência</Button></div><div className="flex gap-2"><Button variant={type==='items'?'default':'outline'} onClick={()=>setType('items')}>Itens</Button><Button variant={type==='models'?'default':'outline'} onClick={()=>setType('models')}>Modelos</Button></div><Card><CardContent className="px-0 pb-0">{loading?<div className="flex items-center gap-2 p-8 text-sm text-muted-foreground"><LoaderCircle className="size-4 animate-spin"/> Carregando correspondências…</div>:<Table><TableHeader><TableRow><TableHead>Nomenclatura recebida</TableHead><TableHead>Destino padronizado</TableHead><TableHead>Situação</TableHead><TableHead>Observação</TableHead><TableHead/></TableRow></TableHeader><TableBody>{rows.map((row:AnyRow)=><TableRow key={row.id} className={row.active?'':'opacity-50'}><TableCell><p className="font-medium">{row.source}</p><p className="text-xs text-muted-foreground">Chave: {row.sourceKey}</p></TableCell><TableCell>{row.target}</TableCell><TableCell><Badge className={row.active?'bg-emerald-50 text-emerald-700':'bg-slate-100 text-slate-600'}>{row.active?'Ativa':'Inativa'}</Badge></TableCell><TableCell className="max-w-72 text-sm text-muted-foreground">{row.notes||'—'}</TableCell><TableCell className="text-right"><Button size="icon-sm" variant="ghost" onClick={()=>setEdit({...row,type})}><Pencil/></Button><Button size="icon-sm" variant="ghost" onClick={()=>remove(row)}><Trash2/></Button></TableCell></TableRow>)}</TableBody></Table>}{!loading&&!rows.length&&<div className="p-10 text-center text-sm text-muted-foreground">Nenhuma correspondência cadastrada. A importação será recusada até que os valores da planilha tenham De/Para.</div>}</CardContent></Card>{edit&&<MappingDialog value={edit} targets={targets} onClose={()=>setEdit(null)} onSave={(body:AnyRow)=>run(async()=>{const path=body.id?`/api/mappings/${body.type}/${body.id}`:`/api/mappings/${body.type}`;await api(path,{method:body.id?'PUT':'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});setEdit(null);await load()},'Correspondência salva.')}/>}</div>;
}

function MappingDialog({value,targets,onClose,onSave}:JsonData){const [form,setForm]=useState<AnyRow>({...value});return <Dialog open onOpenChange={(open)=>!open&&onClose()}><DialogContent><DialogHeader><DialogTitle>{form.id?'Editar':'Nova'} correspondência de {form.type==='items'?'item':'modelo'}</DialogTitle><DialogDescription>O texto recebido será comparado em maiúsculas, sem acentos e com espaços normalizados.</DialogDescription></DialogHeader><div className="space-y-4"><Field label="Nomenclatura recebida *"><Input value={form.source||''} onChange={e=>setForm({...form,source:e.target.value})}/></Field><SelectField label="Destino padronizado *" value={form.targetId||''} onChange={(targetId:string)=>setForm({...form,targetId})} rows={targets.filter((row:AnyRow)=>row.active)}/><Field label="Observação"><Textarea value={form.notes||''} onChange={e=>setForm({...form,notes:e.target.value})}/></Field><div className="flex items-center gap-2 rounded-lg border p-3"><Checkbox id="mapping-active" checked={form.active!==false&&form.active!==0} onCheckedChange={(checked:JsonData)=>setForm({...form,active:!!checked})}/><label htmlFor="mapping-active" className="cursor-pointer text-sm">Correspondência ativa</label></div></div><DialogFooter><Button variant="outline" onClick={onClose}>Cancelar</Button><Button disabled={!form.source||!form.targetId} onClick={()=>onSave(form)}><CheckCircle2/> Salvar</Button></DialogFooter></DialogContent></Dialog>}

function CatalogDialog({open,value,busy,onClose,onSave}:JsonData){const [form,setForm]=useState<AnyRow>(value||{});const t=form.type;return <Dialog open={open} onOpenChange={(x)=>!x&&onClose()}><DialogContent><DialogHeader><DialogTitle>{form.id?'Editar':'Novo'} cadastro</DialogTitle><DialogDescription>Os dados ficarão disponíveis para acordos e importações.</DialogDescription></DialogHeader><div className="space-y-4">{t==='suppliers'&&<><Field label="Nome do fornecedor *"><Input value={form.tradeName||''} onChange={e=>setForm({...form,tradeName:e.target.value})}/></Field><Field label="Razão social"><Input value={form.legalName||''} onChange={e=>setForm({...form,legalName:e.target.value})}/></Field><Field label="CNPJ *"><Input value={form.cnpj||''} onChange={e=>setForm({...form,cnpj:e.target.value})}/></Field></>}{['items','models','brands'].includes(t)&&<Field label="Nome *"><Input value={form.name||''} onChange={e=>setForm({...form,name:e.target.value})}/></Field>}{t==='units'&&<><Field label="Código *"><Input value={form.code||''} onChange={e=>setForm({...form,code:e.target.value})}/></Field><Field label="Descrição *"><Input value={form.name||''} onChange={e=>setForm({...form,name:e.target.value})}/></Field></>}{t==='locations'&&<><Field label="Cidade *"><Input value={form.city||''} onChange={e=>setForm({...form,city:e.target.value})}/></Field><Field label="UF *"><Input maxLength={2} value={form.state||''} onChange={e=>setForm({...form,state:e.target.value.toUpperCase()})}/></Field></>}</div><DialogFooter><Button variant="outline" onClick={onClose}>Cancelar</Button><Button disabled={busy} onClick={()=>onSave(form)}>{busy?<LoaderCircle className="animate-spin"/>:<CheckCircle2/>} Salvar</Button></DialogFooter></DialogContent></Dialog>}
function UserDialog({open,onClose,onSave}:JsonData){const [form,setForm]=useState({name:'',email:'',password:'',role:'viewer'});return <Dialog open={open} onOpenChange={(x)=>!x&&onClose()}><DialogContent><DialogHeader><DialogTitle>Novo usuário autorizado</DialogTitle></DialogHeader><div className="space-y-4"><Field label="Nome *"><Input value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></Field><Field label="E-mail *"><Input type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></Field><Field label="Senha inicial *"><Input type="password" value={form.password} onChange={e=>setForm({...form,password:e.target.value})}/></Field><SelectField label="Perfil" value={form.role} onChange={(v:string)=>setForm({...form,role:v})} rows={[{id:'viewer',name:'Consulta'},{id:'editor',name:'Comprador'},{id:'admin',name:'Administrador'}]}/></div><DialogFooter><Button variant="outline" onClick={onClose}>Cancelar</Button><Button onClick={()=>onSave(form)}>Criar usuário</Button></DialogFooter></DialogContent></Dialog>}

// Le tanto o formato novo (nomenclaturas agrupadas + erros de linha) quanto o
// antigo (sampleErrors), porque o historico guarda importacoes ja feitas.
function ListaErros({resumo}:JsonData){
  if(!resumo) return null;
  const nomenclaturas=resumo.nomenclaturas||[],outros=resumo.outrosErros||[],legado=resumo.sampleErrors||[];
  if(!nomenclaturas.length&&!outros.length&&!legado.length) return null;
  return <div className="mt-2 space-y-3">
    {nomenclaturas.length>0&&<div><p className="mb-1 font-medium">Nomenclaturas sem correspondência ({nomenclaturas.length})</p><ul className="max-h-64 space-y-1 overflow-auto rounded-lg border p-3">{nomenclaturas.map((n:AnyRow,index:number)=><li key={`${n.campo}-${n.valor}-${index}`} className="text-xs"><b>{n.campo}:</b> {n.valor} — {Number(n.linhas).toLocaleString('pt-BR')} linha(s), a partir da linha {n.primeiraLinha}</li>)}</ul>{resumo.nomenclaturasOmitidas>0&&<p className="mt-1 text-xs text-muted-foreground">e mais {resumo.nomenclaturasOmitidas} não exibida(s).</p>}</div>}
    {outros.length>0&&<div><p className="mb-1 font-medium">Outros erros</p><ul className="max-h-64 space-y-1 overflow-auto rounded-lg border p-3">{outros.map((e:AnyRow,index:number)=><li key={`${e.linha}-${index}`} className="text-xs"><b>Linha {e.linha}:</b> {e.erro}</li>)}</ul>{resumo.outrosErrosOmitidos>0&&<p className="mt-1 text-xs text-muted-foreground">e mais {resumo.outrosErrosOmitidos} não exibido(s).</p>}</div>}
    {legado.length>0&&<div><p className="mb-1 font-medium">Erros encontrados</p><ul className="max-h-64 space-y-1 overflow-auto rounded-lg border p-3">{legado.map((e:AnyRow,index:number)=><li key={`${e.row}-${index}`} className="text-xs"><b>Linha {e.row}:</b> {e.error}</li>)}</ul></div>}
  </div>;
}

function ImportFailure({failure}:JsonData){return <Alert variant="destructive"><AlertTriangle/><AlertTitle>Importação não publicada</AlertTitle><AlertDescription><p>{failure.error}</p>{failure.sheet&&<p>Aba: {failure.sheet}</p>}<ListaErros resumo={failure}/></AlertDescription></Alert>}

function Field({label,children,className=''}:JsonData){return <label className={`block ${className}`}><span className="mb-1.5 block text-sm font-medium">{label}</span>{children}</label>}
function SelectField({label,value,onChange,rows,labelFn=(x:AnyRow)=>x.name}:JsonData){return <Field label={label}><NativeSelect className="w-full" value={value} onChange={e=>onChange(e.target.value)}><NativeSelectOption value="">Selecione</NativeSelectOption>{rows.map((x:AnyRow)=><NativeSelectOption key={x.id} value={x.id}>{labelFn(x)}</NativeSelectOption>)}</NativeSelect></Field>}
function Status({value}:JsonData){const map:AnyRow={active:['Vigente','bg-emerald-50 text-emerald-700 ring-1 ring-emerald-200'],expired:['Expirado','bg-red-50 text-red-700 ring-1 ring-red-200'],suspended:['Suspenso','bg-amber-50 text-amber-700 ring-1 ring-amber-200']};const x=map[value]||[value,'bg-slate-100'];return <Badge className={x[1]}>{x[0]}</Badge>}
const statusName=(x:string)=>({active:'Vigente',expired:'Expirado',suspended:'Suspenso'} as AnyRow)[x]||x;
const roleName=(x:string)=>({admin:'Administrador',editor:'Comprador',viewer:'Consulta'} as AnyRow)[x]||x;
function Empty({icon:Icon,title,text}:JsonData){return <Card><CardContent className="grid min-h-72 place-items-center text-center"><div><div className="mx-auto grid size-12 place-items-center rounded-xl bg-muted text-muted-foreground"><Icon/></div><p className="mt-4 font-semibold">{title}</p><p className="mt-1 text-sm text-muted-foreground">{text}</p></div></CardContent></Card>}
